/*
 * Navier-Stokes-Solver 
 * Ported from Processing to P5js by Heiko Gölzer
 * The Processing history seems to go back to https://openprocessing.org/sketch/10412
 * Java implementation of the Navier-Stokes-Solver from
 * http://www.dgp.toronto.edu/people/stam/reality/Research/pdf/GDC03.pdf
 * For now with constant viscosity, no density.
 */

class NavierStokesSolver {
	constructor(N = 26) {
  	this.N = N;
  	this.SIZE = (N + 2) * (N + 2);
  	this.u = new Array(this.SIZE).fill(0);
  	this.v = new Array(this.SIZE).fill(0);
  	this.u_prev = new Array(this.SIZE).fill(0);
  	this.v_prev = new Array(this.SIZE).fill(0);
	}

  getDx(x, y) {
    return this.u[this.getIndex(x + 1, y + 1)];
  }

  getDy(x, y) {
    return this.v[this.getIndex(x + 1, y + 1)];
  }

  applyForce(cellX, cellY, vx, vy) {
    cellX += 1;
    cellY += 1;
    let dx = this.u[this.getIndex(cellX, cellY)];
    let dy = this.v[this.getIndex(cellX, cellY)];
    this.u[this.getIndex(cellX, cellY)] = (vx != 0) ? lerp(vx, dx, 0.85) : dx;
    this.v[this.getIndex(cellX, cellY)] = (vy != 0) ? lerp(vy, dy, 0.85) : dy;
  }

  tick(dt, visc) {
    this.vel_step(this.u, this.v, this.u_prev, this.v_prev, visc, dt);
  }

  getIndex(i, j) {
    return i + (this.N + 2) * j;
  }

  swap(x0, x) {
	let tmp = [];
   	arrayCopy(x0, 0, tmp, 0, this.SIZE);
   	arrayCopy(x, 0, x0, 0, this.SIZE);
   	arrayCopy(tmp, 0, x, 0, this.SIZE);
  }

  diffuse(b, x, x0, diff, dt) {
    let a = dt * diff * this.N * this.N;
    for (let k = 0; k < 20; k++) {
      for (let i = 1; i <= this.N; i++) {
        for (let j = 1; j <= this.N; j++) {
          x[this.getIndex(i, j)] = (x0[this.getIndex(i, j)] + a
            * (x[this.getIndex(i - 1, j)] + x[this.getIndex(i + 1, j)]
            + x[this.getIndex(i, j - 1)] + x[this.getIndex(i, j + 1)]))
            / (1 + 4 * a);
        }
      }
      this.set_bnd(b, x);
    }
  }
	// circular in y
  set_bnd(b, x) {
    for (let i = 1; i <= this.N; i++) {
      x[this.getIndex(0, i)] = (b == 1) ? -x[this.getIndex(1, i)] : x[this.getIndex(1, i)];
      x[this.getIndex(this.N + 1, i)] = b == 1 ? -x[this.getIndex(this.N, i)] : x[this.getIndex(this.N, i)];
      x[this.getIndex(i, 0)] = b == 2 ? x[this.getIndex(i, this.N)] : x[this.getIndex(i, 1)];
      x[this.getIndex(i, this.N + 1)] = b == 2 ? x[this.getIndex(i, 1)] : x[this.getIndex(i, this.N)];
    }
    x[this.getIndex(0, 0)] = 0.5 * (x[this.getIndex(1, 0)] + x[this.getIndex(0, 1)]);
    x[this.getIndex(0, this.N + 1)] = 0.5 * (x[this.getIndex(1, this.N + 1)] + x[this.getIndex(0, this.N)]);
    x[this.getIndex(this.N + 1, 0)] = 0.5 * (x[this.getIndex(this.N, 0)] + x[this.getIndex(this.N + 1, 1)]);
    x[this.getIndex(this.N + 1, this.N + 1)] = 0.5 * (x[this.getIndex(this.N, this.N + 1)] + x[this.getIndex(this.N + 1, this.N)]);
  }

	set_bnd_hard(b, x) {
    for (let i = 1; i <= this.N; i++) {
      x[this.getIndex(0, i)] = (b == 1) ? -x[this.getIndex(1, i)] : x[this.getIndex(1, i)];
      x[this.getIndex(this.N + 1, i)] = b == 1 ? -x[this.getIndex(this.N, i)] : x[this.getIndex(this.N, i)];
      x[this.getIndex(i, 0)] = b == 2 ? -x[this.getIndex(i, 1)] : x[this.getIndex(i, 1)];
      x[this.getIndex(i, this.N + 1)] = b == 2 ? -x[this.getIndex(i, this.N)] : x[this.getIndex(i, this.N)];
    }
    x[this.getIndex(0, 0)] = 0.5 * (x[this.getIndex(1, 0)] + x[this.getIndex(0, 1)]);
    x[this.getIndex(0, this.N + 1)] = 0.5 * (x[this.getIndex(1, this.N + 1)] + x[this.getIndex(0, this.N)]);
    x[this.getIndex(this.N + 1, 0)] = 0.5 * (x[this.getIndex(this.N, 0)] + x[this.getIndex(this.N + 1, 1)]);
    x[this.getIndex(this.N + 1, this.N + 1)] = 0.5 * (x[this.getIndex(this.N, this.N + 1)] + x[this.getIndex(this.N + 1, this.N)]);
  }

  vel_step(u, v, u0, v0, visc, dt) {
    this.diffuse(1, u, u, visc, dt);
    this.diffuse(2, v, v, visc, dt);
    this.project(u, v, u0, v0);
  }

  project(u, v, p, div) {
    let h = 1.0 / this.N;
    for (let i = 1; i <= this.N; i++) {
      for (let j = 1; j <= this.N; j++) {
        div[this.getIndex(i, j)] = -0.5
          * h
          * (u[this.getIndex(i + 1, j)] - u[this.getIndex(i - 1, j)]
          + v[this.getIndex(i, j + 1)] - v[this.getIndex(i, j - 1)]);
        p[this.getIndex(i, j)] = 0;
      }
    }
    this.set_bnd(0, div);
    this.set_bnd(0, p);
    for (let k = 0; k < 20; k++) {
      for (let i = 1; i <= this.N; i++) {
        for (let j = 1; j <= this.N; j++) {
          p[this.getIndex(i, j)] = (div[this.getIndex(i, j)] + p[this.getIndex(i - 1, j)]
            + p[this.getIndex(i + 1, j)] + p[this.getIndex(i, j - 1)] + p[this.getIndex(
            i, j + 1)]) / 4;
        }
      }
      this.set_bnd(0, p);
    }
    for (let i = 1; i <= this.N; i++) {
      for (let j = 1; j <= this.N; j++) {
        u[this.getIndex(i, j)] -= 0.5 * (p[this.getIndex(i + 1, j)] - p[this.getIndex(i - 1, j)]) / h;
        v[this.getIndex(i, j)] -= 0.5 * (p[this.getIndex(i, j + 1)] - p[this.getIndex(i, j - 1)]) / h;
      }
    }
    this.set_bnd(1, u);
    this.set_bnd(2, v);
  }
}


